// scripts/migrate-user-identity.mjs
//
// One-time migration: separate the roster's own identity from Clerk's.
//
// BEFORE  users.id  held the Clerk userId (or a `pending_...` placeholder that
//         was later OVERWRITTEN with the Clerk id on acceptance), and
//         users.email carried a GLOBAL unique constraint.
// AFTER   users.id  is `usr_<uuid>`, generated by us and never reassigned.
//         users.clerk_user_id holds the Clerk identity, nullable until an
//         invited user accepts. Email is unique PER ORG.
//
// Run order (guide 18c — the database moves first, the schema file follows):
//
//   1. node --env-file=.env scripts/migrate-user-identity.mjs            (plan only)
//   2. node --env-file=.env scripts/migrate-user-identity.mjs --apply    (writes)
//   3. npx drizzle-kit push   — should report NO destructive diff on `users`
//
// Step 1 writes nothing. It prints exactly what step 2 would do and refuses to
// continue if anything would violate the new per-org unique indexes, so a
// collision surfaces as a readable list rather than as a failed index build.

import { randomUUID } from 'crypto';
import { db } from '../db/index.js';
import { sql } from 'drizzle-orm';

const APPLY = process.argv.includes('--apply');
const log = (...a) => console.log(...a);
const CLERK_ID = /^user_[A-Za-z0-9]+$/;

const run = async (statement, label) => {
    if (!APPLY) { log(`   would run: ${label}`); return; }
    await db.execute(statement);
    log(`   ran: ${label}`);
};

async function main() {
    log(APPLY ? '\n=== APPLYING ===\n' : '\n=== PLAN ONLY (no writes) — add --apply to execute ===\n');

    // ── 0. Add the column if it is not there yet ─────────────────────────────
    // Idempotent, so a re-run after a partial failure is safe.
    await run(
        sql`ALTER TABLE users ADD COLUMN IF NOT EXISTS clerk_user_id text`,
        'ALTER TABLE users ADD COLUMN IF NOT EXISTS clerk_user_id text'
    );
    if (!APPLY) {
        const [{ exists }] = (await db.execute(sql`
            SELECT EXISTS (
                SELECT 1 FROM information_schema.columns
                WHERE table_name = 'users' AND column_name = 'clerk_user_id'
            ) AS exists
        `)).rows ?? [{ exists: false }];
        if (!exists) {
            log('\n   clerk_user_id does not exist yet. The plan below assumes it will.');
        }
    }

    // ── 1. Read the roster ───────────────────────────────────────────────────
    const rows = (await db.execute(sql`
        SELECT id, org_id, email, name, ${APPLY ? sql`clerk_user_id` : sql`NULL::text AS clerk_user_id`}
        FROM users ORDER BY org_id, email
    `)).rows;
    log(`Roster rows: ${rows.length}\n`);

    // ── 2. Collision pre-check ───────────────────────────────────────────────
    // The new indexes are uniqueIndex(org_id, email) and (org_id, clerk_user_id).
    // Both must be clean BEFORE the index is built, or the build fails with a
    // Postgres error that names the constraint but not the offending rows.
    const seenEmail = new Map();
    const collisions = [];
    for (const r of rows) {
        const key = `${r.org_id}::${(r.email || '').toLowerCase()}`;
        if (seenEmail.has(key)) collisions.push({ key, ids: [seenEmail.get(key), r.id] });
        else seenEmail.set(key, r.id);
    }
    if (collisions.length) {
        log('BLOCKED — duplicate (org_id, email) pairs. Resolve these first:\n');
        for (const c of collisions) log(`   ${c.key}  ->  ${c.ids.join(', ')}`);
        log('\nNothing was changed.');
        process.exit(1);
    }
    log('Collision check: clean — no duplicate (org_id, email) pairs.\n');

    // ── 3. Backfill clerk_user_id from the old id, then renumber ─────────────
    // A `usr_` id is already migrated and is skipped, so this is re-runnable.
    let linked = 0, renumbered = 0, unlinked = 0;
    for (const r of rows) {
        if (String(r.id).startsWith('usr_')) continue;
        const isClerk = CLERK_ID.test(String(r.id));
        const newId = 'usr_' + randomUUID();
        if (isClerk) linked++; else unlinked++;
        renumbered++;
        log(`   ${r.email || r.name}`);
        log(`      id  ${r.id}  ->  ${newId}`);
        log(`      clerk_user_id  ->  ${isClerk ? r.id : 'NULL (never linked to Clerk)'}`);
        if (APPLY) {
            await db.execute(sql`
                UPDATE users
                   SET id = ${newId},
                       clerk_user_id = ${isClerk ? String(r.id) : null},
                       updated_at = NOW()
                 WHERE id = ${String(r.id)}
            `);
        }
    }
    log(`\nRows renumbered: ${renumbered}  (linked to Clerk: ${linked}, unlinked: ${unlinked})\n`);

    // ── 4. Swap the email constraint ─────────────────────────────────────────
    // Drop first, then build. A global unique and a per-org unique can coexist,
    // and if the drop were left until after, the global one would keep rejecting
    // the second org's copy of an address while looking as though it had gone.
    await run(
        sql`ALTER TABLE users DROP CONSTRAINT IF EXISTS users_email_unique`,
        'DROP CONSTRAINT users_email_unique  (the global one)'
    );
    await run(
        sql`CREATE UNIQUE INDEX IF NOT EXISTS users_org_email_uq ON users (org_id, email)`,
        'CREATE UNIQUE INDEX users_org_email_uq (org_id, email)'
    );
    await run(
        sql`CREATE UNIQUE INDEX IF NOT EXISTS users_org_clerk_uq ON users (org_id, clerk_user_id)`,
        'CREATE UNIQUE INDEX users_org_clerk_uq (org_id, clerk_user_id)'
    );
    await run(
        sql`CREATE INDEX IF NOT EXISTS users_clerk_user_id_idx ON users (clerk_user_id)`,
        'CREATE INDEX users_clerk_user_id_idx (clerk_user_id)'
    );

    log(APPLY
        ? '\nDone. Next: npx drizzle-kit push — verify it reports no destructive diff on `users`.'
        : '\nPlan only — nothing was written. Re-run with --apply.');
}

main().then(() => process.exit(0)).catch((e) => {
    console.error('\nMigration failed:', e.message);
    console.error('Nothing after the last "ran:" line above was applied.');
    process.exit(1);
});
